// T09 r15 SOURCE_ONLY: native abort/terminal before instrument release; causal Node delivery before own cleanup.
// Product8s/10s unchanged. One35s Node test budget contains all setup, observation, evidence and own cleanup.
type T09MomentStage='actual-requestfailed'|'native-abort-observed'|'native-terminal-before-release'|'instrumental-release'|'before-own-close'|'fixture-failure-before-probe'|'fixture-failure-before-own-close'|'first-failure-payload-before-io'|'runner-timeout'|'secondary-io-failure'|'cleanup-failure';
interface T09RawMoment {stage:T09MomentStage;bytes:string;writeState:'pending'|'attempted'|'complete'|'unconfirmed'}
function freezeT09Moment(moments:T09RawMoment[],stage:T09MomentStage,raw:unknown):void{moments.push({stage,bytes:JSON.stringify({stage,nodeAt:performance.now(),clock:'Node performance.now; Browser values retained without offset conversion',raw},null,2)+'\n',writeState:'pending'});}
class T09Budget {
 readonly startedAt=performance.now();readonly operationDeadline=this.startedAt+30_000;readonly deadline=this.startedAt+35_000;
 readonly signal:AbortSignal;readonly trace:any;
 constructor(signal:AbortSignal,trace:any){this.signal=signal;this.trace=trace;}
 check():void{if(this.signal.aborted)throw this.signal.reason??new Error('T09_RUNNER_ABORT');if(performance.now()>=this.operationDeadline)throw new Error('T09_OPERATION_BUDGET_NOTREACHED');}
 async wait<T>(label:string,work:()=>Promise<T>,limit=10_000,cleanup=false):Promise<T>{
  const until=cleanup?this.deadline:this.operationDeadline,ms=Math.min(limit,until-performance.now());
  if(ms<=0)throw new Error(cleanup?'T09_CLEANUP_BUDGET_NOTREACHED':'T09_OPERATION_BUDGET_NOTREACHED');
  if(!cleanup&&this.signal.aborted)throw this.signal.reason??new Error('T09_RUNNER_ABORT');
  let timer:ReturnType<typeof setTimeout>|undefined,abort:(()=>void)|undefined;
  try{return await Promise.race([Promise.resolve().then(work),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(new Error(label+'_NOTREACHED')),ms);if(!cleanup){abort=()=>reject(this.signal.reason??new Error('T09_RUNNER_ABORT'));this.signal.addEventListener('abort',abort,{once:true});}})]);}
  finally{clearTimeout(timer);if(abort)this.signal.removeEventListener('abort',abort);}
 }
}
async function writeT09Moments(directory:string,moments:T09RawMoment[],budget:T09Budget,cleanup=false):Promise<void>{
 for(const [index,moment] of moments.entries()){
  if(moment.writeState!=='pending')continue;moment.writeState='attempted';
  try{await budget.wait('T09_MOMENT_IO',()=>writeFile(join(directory,'t09-'+String(index+1).padStart(2,'0')+'-'+moment.stage+'.raw.original.json'),moment.bytes,{flag:'wx',mode:0o600}),10_000,cleanup);moment.writeState='complete';}
  catch(error){moment.writeState='unconfirmed';throw error;}
 }
}

